                    wasm_v128_store(row, wasm_f64x2_sub(wasm_v128_load(row), wasm_f64x2_mul(s0, vi)));
                    wasm_v128_store(row + 2, wasm_f64x2_sub(wasm_v128_load(row + 2), wasm_f64x2_mul(s1, vi)));
